/**
 * 200 response: the return is supported.
 */
export interface CalculateSuccess {
api_version: ApiVersion
tax_year: 2024
supported: true
/**
 * @maxItems 0
 */
reasons: []
outcome: Outcome
lines: Lines
/**
 * Optional (schema 1.1.0). Present only when something in the request was accepted but did not affect the result. Absent means every part of the request was used.
 * 
 * @minItems 1
 */
warnings?: [Warning, ...(Warning)[]]
}
/**
 * Form 1040 line items, one key per scalar output of the Catala Form1040 scope (catala/form_1040.catala_en, 'The scalar output list'). All Money, whole dollars as cents, never negative. Key to form line: api/line-catalog.json. New keys may appear in later minor versions; clients must ignore keys they do not know.
 */
export interface Lines {
wages: Money
employer_income_subtotal: Money
interest_income: Money
total_income: Money
adjustments_to_income: Money
agi: Money
standard_or_itemized_deductions: Money
total_deductions: Money
taxable_income: Money
tentative_tax_from_taxable_income: Money
total_tentative_tax: Money
non_refundable_credits: Money
tax_less_non_refundable_credits: Money
total_tax: Money
total_withholding: Money
total_other_payments_refundable_credits: Money
total_payments: Money
overpayment: Money
balance_due: Money
[k: string]: Money
}
/**
 * A non-fatal note on a 200 response. code is stable: section_not_used = a request section is valid but its Lean module is not wired into the calculator yet, so its values are ignored (none since schema 1.2.0: every section is read); field_superseded (1.2.0) = a schema 1.0 filing_details field that the calculator now derives itself (docs/api-mapping.md), so the value is not used. New codes are additive.
 */
export interface Warning {
code: string
/**
 * RFC 6901 pointer to the part of the request concerned.
 */
path: string
message: string
}
/**
 * 422 response: at least one knockout fired, so no return is computed (no lines).
 */
export interface CalculateUnsupported {
api_version: ApiVersion
tax_year: 2024
supported: false
/**
 * @minItems 1
 */
reasons: [UnsupportedReason, ...(UnsupportedReason)[]]
}
/**
 * One knockout that fired. code is the Catala KnockoutReason constructor name (catala/knockouts_income.catala_en); the list of codes is api/knockout-reasons.json, generated from that enum. New codes are additive: clients must show a generic message for a code they do not know.
 */
export interface UnsupportedReason {
code: string
category: ReasonCategory
/**
 * English fallback text; the frontend owns the final copy.
 */
message: string
}
/**
 * Every non-200, non-422 response. HTTP status: 400 invalid_json/invalid_request/unknown_field/unsupported_api_version/unsupported_tax_year, 404 not_found, 405 method_not_allowed, 413 payload_too_large (body > 256 KiB), 415 unsupported_media_type, 500 internal_error. details is present for 400 only.
 */
export interface ErrorResponse {
api_version: ApiVersion
error: {
code: ErrorCode
message: string
details?: FieldError[]
}
}
export interface FieldError {
/**
 * RFC 6901 JSON Pointer into the request body; empty string = the whole body.
 */
path: string
code: ("required" | "type" | "enum" | "range" | "not_integer" | "unknown_field" | "duplicate_person" | "filer_not_allowed" | "too_many_items" | "invalid_date")
message: string
}
export interface HealthResponse {
status: "ok"
}
export interface VersionResponse {
api_version: ApiVersion
/**
 * Semver of this schema file: patch = docs only, minor = additive, major = breaking (equals api_version).
 */
schema_version: string
tax_year: 2024
/**
 * Git commit of the calculator build
 */
calculator_version: string
}
